import json
from pathlib import Path

# Start with current data
filtered_data = data.copy()

# Read all other polymorph files
polymorph_dir = Path("polymorph_data")
for json_file in polymorph_dir.glob("*_polymorphs.json"):
    if json_file.name != "BN_polymorphs.json":
        try:
            with open(json_file, 'r') as f:
                other_data = json.load(f)
                filtered_data.extend(other_data)
        except:
            pass
"}

